<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {request,type RecordItem} from './api';
import {errorMessage} from './workbench';
const props=defineProps<{token:string;tenantId:string}>();
const emit=defineEmits<{busy:[value:boolean]}>();
type Item={name:string;spec:string;unit:string;quantity:string;product_id:string};
type Order={id:string;business_number:string;version:number;status:string;method:string;confirmed_due_at:string|null;time_note:string;items:Item[];review_reasons:string[];manual_text:string;summary:string};
type Scope={day:string|null;on_date:string|null;method:string|null;phase:string;q:string};
type Bundle={orders:Order[];groups:(Item&{orders:{id:string;business_number:string;quantity:string}[]})[];needs_review:{id:string;business_number:string;reasons:string[]}[];fingerprint:string;generated_at:string;scope:Scope;count:number;notice:string};
type Output={content:string;format:string;filename:string;generated_at:string;includes_contact:boolean;notice:string};
const root=`/api/v1/merchant/tenants/${props.tenantId}`;
const data=ref<Bundle|null>(null),busy=ref(false),error=ref(''),stale=ref(false),view=ref('orders'),day=ref(''),onDate=ref(''),method=ref(''),phase=ref('PREPARING'),search=ref('');
const purpose=ref('PREPARATION'),contact=ref(false),ack=ref(false),output=ref<Output|null>(null),selected=ref<RecordItem|null>(null);
const scope=computed<Scope>(()=>({day:day.value||null,on_date:day.value==='date'?onDate.value||null:null,method:method.value||null,phase:phase.value,q:search.value.trim()}));
const dirty=computed(()=>!!data.value&&JSON.stringify(scope.value)!==JSON.stringify(data.value.scope));
let printCommand:{body:unknown;key:string}|null=null;
let alive=true,epoch=0,timer:ReturnType<typeof setTimeout>|undefined,delay=60000;
function time(value:string|null){return value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+'（北京时间）':'未确定';}
function query(){const p=new URLSearchParams();for(const [key,value] of Object.entries(scope.value))if(value!==null&&value!=='')p.set(key,value);return p.toString();}
function schedule(){if(timer)clearTimeout(timer);if(alive&&!document.hidden)timer=setTimeout(()=>void poll(),delay);}
async function poll(){if(!alive)return;if(busy.value||dirty.value){schedule();return;}const generation=epoch;try{const fresh=await request<Bundle>(root+'/fulfillment?'+query(),props.token);if(alive&&generation===epoch){if(data.value&&fresh.fingerprint!==data.value.fingerprint){stale.value=true;output.value=null;}delay=60000;}}catch{if(alive&&generation===epoch){stale.value=true;error.value='更新检查失败，请重新读取后再导出。';delay=Math.min(delay*2,300000);}}finally{schedule();}}
async function action(fn:(generation:number)=>Promise<void>){if(busy.value)return;const generation=++epoch;busy.value=true;error.value='';emit('busy',true);try{await fn(generation);}catch(e){if(alive&&generation===epoch){error.value=errorMessage(e);stale.value=true;output.value=null;}}finally{if(alive){busy.value=false;emit('busy',false);schedule();}}}
async function load(){await action(async generation=>{const value=await request<Bundle>(root+'/fulfillment?'+query(),props.token);if(alive&&generation===epoch){data.value=value;stale.value=false;output.value=null;selected.value=null;delay=60000;}});}
async function open(id:string){await action(async generation=>{const row=await request<RecordItem>(root+'/reservations/'+id,props.token);if(alive&&generation===epoch)selected.value=row;});}
async function exportFile(format:string){if(!data.value||stale.value||dirty.value)return;const snapshot=data.value;await action(async generation=>{const body={scope:snapshot.scope,expected_fingerprint:snapshot.fingerprint,purpose:purpose.value,format,include_contact:purpose.value==='HANDOVER'&&contact.value,contact_acknowledged:ack.value},key=crypto.randomUUID();const document=await request<Output>(root+'/fulfillment/exports',props.token,'POST',body,key);if(!alive||generation!==epoch)return;output.value=document;printCommand=format==='PRINT'?{body,key}:null;if(format!=='PRINT'){const url=URL.createObjectURL(new Blob([format==='CSV'?'\ufeff':'',document.content],{type:format==='CSV'?'text/csv;charset=utf-8':'text/plain;charset=utf-8'}));const a=window.document.createElement('a');a.href=url;a.download=document.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),0);}});}
async function print(){if(output.value?.format!=='PRINT'||stale.value||dirty.value||!printCommand)return;const command=printCommand;await action(async generation=>{await request(root+'/fulfillment/exports',props.token,'POST',command.body,command.key);if(alive&&generation===epoch)window.print();});}
onMounted(()=>{void load();});onUnmounted(()=>{alive=false;epoch++;if(timer)clearTimeout(timer);data.value=null;selected.value=null;output.value=null;printCommand=null;emit('busy',false);});
</script>
<template><section aria-label="今日备货与交付清单" :aria-busy="busy"><div class="non-print"><h2>今日备货与交付清单</h2><p>沿用待办日期与交付方式口径，默认只选已确认/备货中。未确认、取消、完成项不纳入；不换算单位。</p>
<p v-if="error" role="alert" class="error">{{error}}</p><p v-if="stale||dirty" role="status" class="notice">范围已变或记录可能更新，请重新读取清单；旧导出不是实时状态。</p>
<div class="row"><label>范围日期<select v-model="day" :disabled="busy"><option value="">全部日期（限200单）</option><option value="today">今天</option><option value="tomorrow">明天</option><option value="date">指定日期</option><option value="none">未指定时间</option></select></label><label v-if="day==='date'">指定日期<input type="date" v-model="onDate" :disabled="busy"/></label><label>交付方式<select v-model="method" :disabled="busy"><option value="">全部方式</option><option value="PICKUP">自提</option><option value="DELIVERY">配送</option></select></label><label>业务范围<select v-model="phase" :disabled="busy"><option value="PREPARING">已确认/备货中</option><option value="DELIVERY">待取送/配送中</option><option value="ACTIVE">全部已确认非终态</option></select></label></div><label>沿用文字/业务号搜索<input v-model="search" maxlength="200" :disabled="busy"/></label><button :disabled="busy" @click="load">重新读取清单</button>
<template v-if="data"><p>本店 {{data.count}} 单 · 生成于 {{time(data.generated_at)}}。{{data.notice}}</p><button @click="view='orders'">按单查看</button><button @click="view='products'">按商品汇总</button>
<div v-if="view==='orders'"><article v-for="order in data.orders" :key="order.id"><h3>{{order.business_number}} · {{order.status}} · {{order.method}}</h3><p>明确时间 {{time(order.confirmed_due_at)}} / {{order.time_note}}</p><ul><li v-for="(item,i) in order.items" :key="i">{{item.name}} · {{item.spec}} · {{item.quantity}} {{item.unit}}</li></ul><p class="notice" v-if="order.review_reasons.length">{{order.review_reasons.join('；')}}</p><p class="raw" v-if="order.manual_text">原文（仅店内核对，不随默认导出）：{{order.manual_text}}</p><button :disabled="busy" @click="open(order.id)">重新鉴权查看 {{order.business_number}}</button></article></div>
<div v-else><article v-for="(group,i) in data.groups" :key="i"><h3>{{group.name}} · {{group.spec}} · {{group.quantity}} {{group.unit}}</h3><details><summary>追溯来源 {{group.orders.length}} 单</summary><button v-for="order in group.orders" :key="order.id" :disabled="busy" @click="open(order.id)">{{order.business_number}} · {{order.quantity}}{{group.unit}}</button></details></article></div>
<div aria-label="需人工核对"><h3>需核对，不计入汇总</h3><p v-for="row in data.needs_review" :key="row.id">{{row.business_number}} · {{row.reasons.join('；')}}</p></div>
<article v-if="selected" aria-label="清单来源记录"><h3>{{selected.business_number}} · 当前版本 {{selected.version}}</h3><p>{{selected.status}}</p><p class="raw">{{selected.raw_text}}</p><p>仅查看不改变状态；确认/交付仍在「记单与待办」明确操作。</p><button @click="selected=null">关闭来源记录</button></article>
<fieldset :disabled="busy||stale||dirty"><legend>限量导出/打印（不改变备货或交付状态）</legend><label>文件用途<select v-model="purpose" @change="contact=false;ack=false;output=null"><option value="PREPARATION">备货单（默认不含联系信息）</option><option value="HANDOVER">配送/自提清单</option></select></label><template v-if="purpose==='HANDOVER'"><label class="check"><input type="checkbox" v-model="contact" @change="ack=false;output=null"/>按交付用途包含联系人、完整电话及配送地址</label><label v-if="contact" class="check"><input type="checkbox" v-model="ack"/>已核对用途，将妥善保管含个人信息的文件</label></template><div class="actions"><button :disabled="contact&&!ack" @click="exportFile('CSV')">下载CSV</button><button :disabled="contact&&!ack" @click="exportFile('TEXT')">下载文本</button><button :disabled="contact&&!ack" @click="exportFile('PRINT')">生成打印清单</button></div></fieldset><p>CSV按文本引用，不要移除保护或另存后执行公式。打印分页/纸面效果未验收。</p>
</template></div><article v-if="output" class="print-document" aria-label="生成的清单"><div class="non-print"><p>{{output.notice}} · {{output.includes_contact?'包含个人联系信息':'未包含联系字段'}} · {{time(output.generated_at)}}</p><button v-if="output.format==='PRINT'" :disabled="busy||stale||dirty" @click="print">打印此清单</button><button @click="output=null">清除已生成清单</button></div><pre>{{output.content}}</pre></article></section></template>
<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.8 system-ui,sans-serif}.print-document{border:1px solid #b8c8bf;padding:16px}@media print{.non-print{display:none!important}.print-document{border:0;padding:0;break-inside:auto}pre{font-size:11pt}}</style>
<style>@media print{body{background:white}main{max-width:none;padding:0}main>header,main>.login,main>nav,main>.row,main>p,main>button,nav[aria-label="工作台功能"]{display:none!important}section[aria-label="今日备货与交付清单"]{border:0;margin:0;padding:0}}</style>
